"""Apply the figure and sentence-level edits to a COPY of the LaTeX project. Locked units (abstract, introduction,
related work, setup, conclusion) are not touched. Every text replacement asserts that the original is present once."""
import sys, pathlib
root=pathlib.Path(sys.argv[1])
def sub(path,old,new):
    p=root/path; s=p.read_text(encoding='utf-8'); assert s.count(old)==1,(path,old[:50],s.count(old)); p.write_text(s.replace(old,new),encoding='utf-8')
def write(path,text): (root/path).write_text(text,encoding='utf-8')
def fig(name,file,caption,label):
    write(f'revised_sections/{name}.tex',"\\begin{figure*}[t]\n\\centering\n\\includegraphics[width=\\textwidth]{revised_figures/%s}\n\\caption{%s}\n\\label{%s}\n\\end{figure*}\n"%(file,caption.strip(),label))
sub('main.tex','revised_figures/figure1.pdf','revised_figures/figure1_v3.pdf')
write('revised_sections/figure1_caption.tex',r"""\textbf{Where visual responses are read and restored in frozen $\pi_{0.5}$.}
(a) A clean and a perturbed observation of the same physical state pass through the policy with the same initial noise (main camera shown; the wrist view is also an input). After action-expert layers L1, L9 and L18 we record the response $\Delta H_\ell = H^{p}_\ell - H^{c}_\ell$ and fit 16 shared directions per layer, which retain 36.5--83.6\% of held-out response energy against at most 10.2\% for equal-rank controls (Fig.~\ref{fig:token-structure}). Restoration writes their clean coordinates back into the state leaving L9 at every generation step, removing the shared part of $\Delta H_9$.
(b) Paired change from unedited generation (dots: means; bars: simultaneous 95\% intervals). The clean-reference error of the first five translation commands falls, and observed task success is higher by 1.85 (Camera) and 3.33 (Sensor Noise) percentage points, with intervals that include zero (Fig.~\ref{fig:native-restoration}).
""")
fig('float_measurements','figure2_v3.pdf',r"""\textbf{How responses are recorded, restored and evaluated over time.}
(a) At each query the prefix is computed once and the action expert refines the whole plan over ten Euler steps from noise $x_0$ (ten actions for $\pi_{0.5}$); the first five commands are executed before a new observation starts the next query.
(b) Recordings: clean and perturbed branches share $x_0$ and then update their plans separately; the response $\Delta H_{\ell,j}$ is taken at every generation step $j$ and sampled layer $\ell$.
(c) Restoration: at every step of every query, a clean reference is computed at the intervention run's current state, plan sample and generation time, and its coordinates along the 16 shared directions are written after L9; generation continues with the perturbed prefix.
(d) Execution study: from one matched state, clean runs $R_0$, $R_1$ and perturbed runs $T_0$, $T_1$ use two policy-noise inputs, and $R'_0$ repeats $R_0$. Separation between $T_i$ and $R_i$ after 5 and 60 issued controls is compared with that between $R_0$ and $R_1$, the clean-resampling reference; the trajectories drawn are schematic.
""",'fig:model-measurement')
fig('float_geometry','figure3_geometry_v3.pdf',r"""\textbf{Response coverage and fixed affine command prediction favor different layers.} Internal recordings: the same 404 pairs on 28 common tasks, with joint task/family holdout; small dots are tasks. (a) Centered initial-step response energy retained by 16 directions, with pointwise 95\% task intervals. (b) Translation-command MSE of a fixed affine readout divided by the family-mean MSE of predicting no change; large markers are ratios of task means, and the shaded region is better than that prediction. L1 retains the most response energy, while L18 gives the lowest prediction error. Paired basis comparisons: Supplement, Secs.~S3.4 and S18.""",'fig:token-structure')
fig('float_restoration','figure4_restoration_v3.pdf',r"""\textbf{Restoring shared response coordinates reduces initial-command error, and observed task success is higher.}
Independent all-step L9 confirmation on 31 tasks; one row per arm, with response restoration shaded. (a) Mean error of the first five issued translation commands relative to paired native-clean commands, and the per-task reduction of each control arm relative to response restoration. All six simultaneous 95\% intervals are positive; the last column counts tasks with a positive difference. Error axes differ between families, and each basis restores its own coordinate difference, so write magnitudes differ. (b) Primary endpoint: task-equal success by arm, and its difference from response restoration with simultaneous 95\% intervals over six comparisons. Against the unedited policy, success is higher by $+1.85\;[-8.33,\,11.11]$ and $+3.33\;[-1.67,\,9.17]$ percentage points. Complete controls: Supplement, Sec.~S13.""",'fig:native-restoration')
fig('float_outcomes','figure5_outcomes_v3.pdf',r"""\textbf{Small early motion can accompany success losses, and zero net change can hide outcome flips.} Independent executions of the unedited policies on 28 common tasks; each comparison matches the initial physical state and policy noise. (a) End-effector separation after five controls relative to that between two clean runs with different policy noise (ratio of task-equal means, 95\% interval), against the change in task success (four-family-adjusted 98.75\% interval); grey bands join the two policies of a family. Under Sensor Noise, $\pi_0$ moves 0.58 times its clean-resampling separation yet loses 14.3 percentage points. (b) The same ratio for every task (grey dots), and task-equal rates of lost and gained successes; for $\pi_{0.5}$ under Background both are 3.57\%. (c) All 110 $\pi_0$ Sensor Noise pairs: S, success; F, failure (clean$\to$perturbed); the right column counts pairs below their own clean-resampling reference. \dag\,For Light, some outcomes were not recorded: its marks use recorded outcomes only and carry no success interval, and its motion covers 43/48 settings on 26 tasks ($\pi_{0.5}$) and 44/48 on 27 ($\pi_0$). Bounds over the unrecorded outcomes and control-60 ratios are in the Supplement (Secs.~S6 and S18; Table~S9).""",'fig:behavior')
sub('revised_sections/structured.tex',r"obtained by replacing all 1024 channels (Supplement, Tables~S32--S33).",
 r"obtained by replacing all 1024 channels (Supplement, Tables~S32--S33). The reduction is uneven across tasks: 25 of 27 Camera and 24 of 30 Sensor tasks improve, with medians (0.056, 0.006) below the means.")
sub('revised_sections/structured.tex',r"Observed task success rises from 73.15\% to 75.00\% for Camera and from 83.33\% to 86.67\% for Sensor, toward the clean baselines reported in Fig.~\ref{fig:native-restoration}. The figure places these primary outcomes beside command correction and gives the paired success gains with simultaneous 95\% intervals over six success comparisons; the two displayed intervals include zero.",
 r"Observed task success is also higher after response restoration: by 1.85 percentage points for Camera (73.15\% to 75.00\%) and by 3.33 for Sensor (83.33\% to 86.67\%), toward clean baselines of 98.15\% and 97.50\% (Fig.~\ref{fig:native-restoration}b). The simultaneous 95\% intervals over the six success comparisons are $[-8.33,11.11]$ and $[-1.67,9.17]$ percentage points; both include zero, so the size of the gain is not yet precisely estimated. In paired cases, restoration turns 7 unedited failures into successes and 5 successes into failures under Camera, and 7 and 3 under Sensor.")
sub('revised_sections/motion.tex',r"is $[-28.6,-2.7]$ percentage points (Fig.~\ref{fig:behavior}a,b).",
 r"is $[-28.6,-2.7]$ percentage points (Fig.~\ref{fig:behavior}a,b). By control 60 the motion ratio is $0.97\ [0.70,1.34]$ (Supplement, Table~S9): the small separation describes the early window, not the whole episode.")
sub('revised_sections/motion.tex',r"(post-hoc descriptive breakdown; Supplement, Table~S10).",
 r"(post-hoc descriptive breakdown; Supplement, Table~S10). Among the 102 pairs that start from a clean success, the early-separation ratio gives an AUROC of $0.49\ [0.29,0.70]$ for lost versus retained successes (Fig.~\ref{fig:behavior}d).")

# Figure 5 after the redesign: a = motion against success, b = every task and outcome flips, c = pairs by outcome
_p=root/'revised_sections/motion.tex'; _t=_p.read_text(encoding='utf-8')
assert _t.count(r"\ref{fig:behavior}a,b)")==2 and _t.count(r"\ref{fig:behavior}d)")==1 and _t.count(r"\ref{fig:behavior}c)")==1
_t=_t.replace(r"\ref{fig:behavior}c)",r"\ref{fig:behavior}b)").replace(r"\ref{fig:behavior}d)",r"\ref{fig:behavior}c)").replace(r"\ref{fig:behavior}a,b)",r"\ref{fig:behavior}a)")
_p.write_text(_t,encoding='utf-8')
